27|pub struct Policy {
28|    pub version: u32,
29|    /// Explicit Unix operator UID; zero is allowed only as operator bootstrap.
30|    /// No logical principal is inferred from this UID.
31|    pub operator_uid: u32,
32|    pub host_members: Vec<MemberPolicy>,
33|    #[serde(default)]
