43|impl Policy {
44|    pub fn validate(&self) -> Result<()> {
45|        ensure!(self.version == 1, "unsupported policy version");
46|        let expected = [
47|            ("home", "/home", "6a879d99-6b08-4741-8747-595776fc12f0", ROOT_FS),
48|            ("logs", "/var/log", "23a2e07c-c299-3143-a13b-24308233650a", HOST_FS),
49|            ("cargo-build", "/var/lib/cargo-build", "f11d6f27-8ed6-cb46-8949-4ab9cf36b8d9", HOST_FS),
50|            ("opt", "/opt", "53f86daf-f5ee-4c4f-b6b9-b3e9361b78e5", HOST_FS),
51|            ("golden", "/opt/op-dbus/golden", "c8e1fc74-79f1-a54d-91d5-0b7ce42b9cd5", HOST_FS),
52|            ("git", "/srv/git", "675ae8d1-ae56-5a4f-b87b-86b0d7d90397", HOST_FS),
53|            ("rootfs", "/", "127b5d01-f8e8-b34a-8905-65a58657f1e2", ROOT_FS),
54|        ];
55|        ensure!(self.host_members.len() == expected.len(), "host set must contain all seven pinned members");
56|        if let Some(admission) = &self.admission {
57|            ensure!(admission.bus_name == crate::admission::ADMISSION_BUS && admission.cgroup == "/opdbus-admission", "unassigned admission service identity");
58|            crate::objects::checked_absolute(&admission.executable.path)?;
59|            ensure!(admission.executable.sha256.len() == 64 && admission.executable.sha256.bytes().all(|c| c.is_ascii_hexdigit())
60|                && admission.executable.inode > 0
61|                && (admission.executable.filesystem_uuid == ROOT_FS || admission.executable.filesystem_uuid == HOST_FS)
62|                && !uuid::Uuid::parse_str(&admission.executable.subvolume_uuid)?.is_nil(), "admission executable pin absent");
63|        }
64|        ensure!(self.capture_scopes.len() <= 8, "too many capture scopes");
65|        let mut capture_ids = BTreeSet::new();
66|        let mut capture_sources = BTreeSet::new();
67|        let mut capture_parents = BTreeSet::new();
68|        for scope in &self.capture_scopes {
69|            ensure!(!scope.scope_id.is_empty() && capture_ids.insert(&scope.scope_id), "duplicate/empty capture scope");
70|            validate_pin(&scope.snapshot_parent)?;
71|            ensure!(capture_parents.insert(&scope.snapshot_parent.path), "capture owners need distinct snapshot parents");
72|            ensure!(scope.snapshot_parent.filesystem_uuid == HOST_FS, "capture source filesystem not enrolled");
73|            let expected: Vec<&str> = match scope.workflow {
74|                crate::protocol::CaptureWorkflow::VectorDump => vec!["timing", "vectors"],
75|                crate::protocol::CaptureWorkflow::Development => vec!["git"],
76|                crate::protocol::CaptureWorkflow::Cache => anyhow::bail!("cache lifecycle is not restored/enrolled"),
77|            };
78|            let actual: BTreeSet<_> = scope.members.iter().map(|m| m.member.as_str()).collect();
79|            ensure!(actual == expected.into_iter().collect() && actual.len() == scope.members.len(), "capture member set mismatch");
80|            for member in &scope.members {
81|                validate_pin(&member.source)?;
82|                ensure!(capture_sources.insert(&member.source.path), "capture source assigned to multiple lifecycles");
83|                let path = match member.member.as_str() {
84|                    "timing" => "/opt/op-dbus/vector-store/timing",
85|                    "vectors" => "/opt/op-dbus/vector-store/vectors",
86|                    "git" => "/srv/git",
87|                    _ => unreachable!(),
88|                };
89|                ensure!(member.source.path == path && member.source.inode == 256
90|                    && member.source.filesystem_uuid == HOST_FS, "capture source object not enrolled");
91|            }
92|            if scope.workflow == crate::protocol::CaptureWorkflow::VectorDump {
93|                let lock = scope.writer_lock.as_ref().context("vector writer lock missing")?; validate_pin(lock)?;
94|                ensure!(lock.path == "/opt/op-dbus/vector-store/.writer.lock", "vector writer lock path mismatch");
95|            }
96|            if let Some(parent) = &scope.receive_parent {
97|                validate_pin(parent)?; ensure!(parent.filesystem_uuid == ROOT_FS, "capture receive filesystem not enrolled");
98|                let executable = self.capture_receive_executable.as_ref().context("capture receiver executable missing")?;
99|                ensure!(executable.path == "/usr/bin/btrfs" && executable.filesystem_uuid == ROOT_FS
100|                    && !uuid::Uuid::parse_str(&executable.subvolume_uuid)?.is_nil() && executable.sha256.len() == 64, "capture receiver identity absent");
101|            }
102|        }
103|        if let Some(provision) = &self.vector_provision {
104|            validate_pin(&provision.base)?;
105|            ensure!(provision.base.path == "/opt/op-dbus/vector-store" && provision.base.filesystem_uuid == HOST_FS, "vector provisioning base not enrolled");
106|        }
107|        let mut names = BTreeSet::new();
108|        let mut destinations = BTreeSet::new();
109|        for member in &self.host_members {
110|            ensure!(names.insert(&member.member), "duplicate host member");
111|            let (_, path, uuid, fs) = expected.iter().find(|e| e.0 == member.member)
112|                .context("unknown host member")?;
113|            ensure!(member.source.path == *path && member.source.subvolume_uuid == *uuid
114|                && member.source.filesystem_uuid == *fs && member.source.inode == 256,
115|                "host source does not match pinned layout");
116|            validate_pin(&member.source)?;
117|            validate_pin(&member.destination_parent)?;
118|            ensure!(member.destination_parent.filesystem_uuid == *fs, "cross-filesystem snapshot forbidden");
119|            ensure!(member.destination_parent.path != member.source.path, "destination cannot be source root");
120|            // Dedicated owner-only directories, deliberately enrolled by the operator.
121|            ensure!(destinations.insert(&member.destination_parent.path), "members need distinct owned destination parents");
122|        }
123|        Ok(())
124|    }
